#[test]fn original_common_and_wrapper_records_match_all_game_fields_and_prefixes(){let Some(root)=std::env::var_os("NATIVE_COMMON_CALLER_DIRECTORY")else{return;};for name in["V45-common-hardware-whole.jsonl","V46-common-hardware-initialized-follow.jsonl","V45-common-hardware-counters.jsonl","V45-common-hardware-returns.jsonl","V46-common-hardware-acquire-parity.jsonl","V46-common-hardware-acquire-targets.jsonl"]{let rows=std::fs::read_to_string(std::path::Path::new(&root).join(name)).unwrap().lines().map(|l|serde_json::from_str::<Value>(l).unwrap()).collect::<Vec<_>>();let expected=match name{"V45-common-hardware-whole.jsonl"=>32,"V46-common-hardware-initialized-follow.jsonl"=>32,"V45-common-hardware-counters.jsonl"=>16,"V45-common-hardware-returns.jsonl"=>10,"V46-common-hardware-acquire-parity.jsonl"=>8,"V46-common-hardware-acquire-targets.jsonl"=>30,_=>unreachable!()};assert_eq!(rows.len(),expected*2,"{name}:complete expected dataset");for pair in rows.chunks_exact(2){let a=&pair[0];let b=&pair[1];let mut g=fixture(a);let label=format!("{name}/f{}/mode{}/mp{}",a["family"],a["mode"],a["mp"]);if a["mode"]==20{assert!(g.dispatch_native_hardware_common(0));}else{let mut e=Env{game:&mut g,index:0,movement:Hardware::Dummy,probe_crt:true};let result=super::super::run(&mut e);if b["boundary"]=="ExternalCRTrand"{assert_eq!(result,Err(error(Missing::CrtPrefix)),"{label}");}else{assert_eq!(result,Ok(()),"{label}");}}compare(&format!("{label} unit192"),&project(&g,a,0,"unit"),&bytes(b["unit"].as_str().unwrap()));compare(&format!("{label} peer192"),&project(&g,a,1,"leader"),&bytes(b["leader"].as_str().unwrap()));compare(&format!("{label} roster72"),&g.native_group_rosters.pool[0].roster,&bytes(b["group"].as_str().unwrap()));compare(&format!("{label} W44"),&g.native_hardware_pool[0].attributes.bytes,&bytes(b["hardware"].as_str().unwrap()));compare(&format!("{label} dummy44"),&g.native_hardware_dummy_attributes.bytes,&bytes(b["dummy"].as_str().unwrap()));let primary=g.native_routes.borrow().pool.nodes.iter().take(8).flat_map(|n|n.point.iter().flat_map(|n|n.to_le_bytes()).chain(n.next.to_le_bytes())).collect::<Vec<_>>();compare(&format!("{label} primary64"),&primary,&bytes(b["primary"].as_str().unwrap()));if let Some(peer)=b["peerHardware"].as_str(){compare(&format!("{label} peerW44"),&g.native_hardware_pool[1].attributes.bytes,&bytes(peer));}assert_eq!(g.native_group_rosters.current_roster.map(|n|0x60ec00+n*72),b["context"].as_u64().map(|n|n as usize),"{label}:actual632194context");if let Some(h)=b["poolHash"].as_u64(){let bytes=g.native_routes.borrow().pool.nodes.iter().flat_map(|n|n.point.iter().flat_map(|n|n.to_le_bytes()).chain(n.next.to_le_bytes())).collect::<Vec<_>>();assert_eq!(fnv(&bytes),h as u32,"{label}:whole14400nodepool");assert_eq!(fnv(&g.native_smoke20.tracks.bytes()),b["tracksHash"].as_u64().unwrap()as u32,"{label}:500trackrecords");assert_eq!(fnv(&g.native_smoke20.bytes()),b["smokeHash"].as_u64().unwrap()as u32,"{label}:20smokerecords");}assert_eq!(g.native_hardware_common.saved_control06,b["saved06"].as_u64().unwrap()as u8,"{label}");assert_eq!(g.native_hardware_common.gate,b["gate"].as_u64().unwrap()as u8,"{label}");assert_eq!(g.original_rng.words,std::array::from_fn(|i|b[format!("r{i}")].as_u64().unwrap()as u32),"{label}:all5RNG");}}}

