#[test]fn main_owns_each_common_phase_once_and_default60_keeps_shared_bytes(){let mut pictures=Vec::new();for phase in[9,10,53,54,55,58,60]{let mut g=ordinary(phase);g.native_hardware_common=Shared{saved_control06:73,gate:173,movement_byte:5};let w=g.units[0].native_hardware_slot.unwrap();g.native_hardware_pool[w].attributes.bytes[4]=0xf2;g.units[0].native_flags9c=1;g.step(0.059);assert_eq!(g.native_route_boundary,None,"phase{phase}");assert_eq!(g.native_hardware_common.movement_byte,0,"435b51 reset precedesparkedcommon");assert_eq!(g.native_unit_loop_index,240);assert!(!g.native_unit_loop_active);assert_eq!(g.units[0].native_phase35,phase,"sourcewrapperpostphase");assert_eq!(g.units[0].native_common_callback,Some(g.motion_tick));assert_eq!(g.units[0].native_counter68,if phase==60{8}else{7},"exactlyonecommonDEC68 phase{phase}");assert_eq!(g.native_hardware_pool[w].attributes.bytes[4],if phase==60{0xf2}else{0xf1},"W4clampedonce");if phase==58{assert_eq!(g.units[0].native_flags9c&1,0);}if phase==60{assert_eq!(g.native_hardware_common.saved_control06,73);/* Other liveUNIT may subsequently own the shared gate. */}pictures.push(crate::game_snapshot(&g,&serde_json::json!({})));}if let Some(path)=std::env::var_os("NATIVE_COMMON_RPC_OUTPUT"){std::fs::write(path,serde_json::to_vec(&pictures).unwrap()).unwrap();}}
#[test]fn main_walk_reaches_real_finite_head_and_uses_only_one_common_movement_callback(){let mut g=ordinary(9);let slot=g.units[0].native_slot.unwrap();let end=[348,328];let head=g.native_routes.get_mut().pool.allocate_goal(end).unwrap();g.native_routes.get_mut().pool.links[slot].primary=head;g.native_routes.get_mut().managed[slot]=true;g.units[0].path=g.native_owned_route_view(0).unwrap();assert!(g.record_native_order_event(0,crate::original_orders_game::Event::classified(1,end,0)));let mut moved=false;for _ in 0..80{let old=g.units[0].x;g.winner=None;g.step(0.059);assert_eq!(g.native_route_boundary,None);let delta=g.units[0].x-old;assert!((0. ..=4.).contains(&delta),"single59mspositioncommit {delta}");moved|=delta>0.;if g.units[0].x==680.{break;}}assert!(moved);assert_eq!((g.units[0].x,g.units[0].y),(680.,640.));assert_eq!(g.native_routes.borrow().pool.links[slot].primary,0);}
#[test]fn pending_w17_ignores_pause69_but_obeys_contact31_and_never_double_steps(){for paused in[false,true]{for contact in[false,true]{let mut g=ordinary(9);let slot=g.units[0].native_slot.unwrap();let head=g.native_routes.get_mut().pool.allocate_goal([408,328]).unwrap();g.native_routes.get_mut().pool.links[slot].primary=head;g.native_routes.get_mut().managed[slot]=true;let w=g.units[0].native_hardware_slot.unwrap();let mut order=g.native_hardware_pool[w].order;order.field17=2;g.native_hardware_pool[w].set_order(order);let m=g.native_group_rosters.members[slot].as_mut().unwrap();if paused{m.flags69|=8;}if contact{m.flags31|=64;}g.native_hardware_common_body(0).unwrap();assert_eq!(g.units[0].x,640.,"pending starts52810withoutmovement");assert_eq!(g.native_hardware_pool[w].order.field17,if contact{2}else{1});assert_eq!(g.units[0].original_motion.is_some(),!contact);}}}
