#[test]fn real_crane_caller_delegates_common_once_and_preserves_its_own59_state(){let mut g=field();g.spawn("crane",0,640.,640.,1,None);g.spawn("medium",1,3600.,3600.,2,None);g.maintain_native_group_rosters();g.native_group_rosters.observe_unit_context(g.units[0].native_slot.unwrap());g.prepare_native_ambient_queries();g.import_native_world(&serde_json::json!({"nativeCraneBuildFrames":vec![vec![[0,0,1,0];6];12]}));let slot=g.units[0].native_slot.unwrap();g.record_native_crane_ctor(0);g.units[0].native_phase35=59;g.units[0].native_counter68=8;let work=g.native_crane_work9a(slot,g.units[0].id).unwrap();assert!(g.update_native_crane_building(0,1,1));assert_eq!(g.native_route_boundary,None);assert_eq!(g.units[0].native_phase35,59);assert_eq!(g.units[0].native_counter68,7);assert_eq!(g.native_crane_work9a(slot,g.units[0].id).unwrap(),work);assert_eq!(g.units[0].native_common_callback,Some(g.motion_tick));}
#[test]fn source_shared_bytes_survive_mission_construction_and_new_units(){let mut g=ordinary(60);g.native_hardware_common=Shared{saved_control06:73,gate:173,movement_byte:5};crate::GAME.with(|c|*c.borrow_mut()=Some(g));crate::request(serde_json::json!({"op":"init","mission":1,"seed":12}));crate::GAME.with(|c|assert_eq!(c.borrow().as_ref().unwrap().native_hardware_common,Shared{saved_control06:73,gate:173,movement_byte:5}));}
#[test]fn coupled_source_reset_common_work_byte_preserves_warm_values_and_audio_boundaries(){let Some(root)=std::env::var_os("NATIVE_COMMON_CALLER_DIRECTORY")else{return;};let rows=std::fs::read_to_string(std::path::Path::new(&root).join("V46-common-movement-byte.jsonl")).unwrap().lines().map(|l|serde_json::from_str::<Value>(l).unwrap()).collect::<Vec<_>>();assert_eq!(rows.len(),384);let mut completed=0;let mut audio_prefix=0;for chunk in rows.chunks_exact(4){let b=&chunk[1];let c=&chunk[2];let d=&chunk[3];let mut g=fixture(b);let mode=b["mode"].as_u64().unwrap();let camera=if mode/3%2==0{0}else{1000};g.native_view=Some(([camera,0],[1024,1024]));g.native_hardware_common.movement_byte=b["cue"].as_u64().unwrap()as u8;g.native_hardware_common_body(0).unwrap();assert_eq!(g.native_hardware_common.movement_byte,c["cue"].as_u64().unwrap()as u8);compare("coupledcommonUNIT192",&project(&g,b,0,"unit"),&bytes(c["unit"].as_str().unwrap()));if d["boundary"]=="CraneSamplePrefix"{audio_prefix+=1;assert_eq!(d["cue"],c["cue"],"no inventedterminalwritebefore46e660returns");}else{completed+=1;assert!(d["boundary"].as_str().unwrap().is_empty());let terminal=d["workFrame"]==11;assert_eq!(g.native_common_work_terminal(0,terminal),d["returnAL"]==1);assert_eq!(g.native_hardware_common.movement_byte,d["cue"].as_u64().unwrap()as u8);}}assert_eq!((completed,audio_prefix),(72,24));}

#[test]fn positive_role_main_prepass_restores_control_and_sign_extends_the_actual_low_frame(){let mut g=field();g.spawn("medium",0,608.,640.,10,None);g.spawn("medium",0,640.,640.,10,None);g.spawn("medium",1,3600.,3600.,20,None);g.maintain_native_group_rosters();let slot=g.units[1].native_slot.unwrap();assert_eq!(g.native_group_rosters.role(slot),Some(1));let leader=g.units[0].native_slot.unwrap();g.native_group_rosters.members[leader].as_mut().unwrap().flags69|=64;let group=g.native_group_rosters.group_slot(0,10).unwrap();g.native_group_rosters.pool[group].roster[63]=0;g.native_group_rosters.pool[group].roster[10..12].copy_from_slice(&384u16.to_le_bytes());let head=g.native_routes.get_mut().pool.allocate_goal([408,328]).unwrap();g.native_routes.get_mut().pool.links[slot].primary=head;g.native_routes.get_mut().managed[slot]=true;assert!(!g.resume_native_reset_path(1),"52810 AL0 started the source line");g.units[1].native_phase35=9;g.units[1].native_frame32=0x12fe;g.units[1].native_timer3c=5;g.units[1].native_control06=10;g.units[1].native_counter68=8;g.multiplayer=true;g.original_rng.multiplayer=true;g.step(0.059);assert_eq!(g.native_route_boundary,None);assert_eq!(g.units[1].native_counter68,7);assert_eq!(g.native_hardware_common.saved_control06,10);assert_eq!(g.units[1].native_control06,10);assert!((-128..128).contains(&g.units[1].native_frame32),"saveBH/restoreMOVSX,notoldwholeword");assert_eq!(g.units[1].native_phase35,9);assert_eq!(g.units[1].native_common_callback,Some(g.motion_tick));}

#[test]fn a_blocked_directed_query_does_not_require_the_object_pool_or_toggle_its_phase(){let mut g=ordinary(9);g.native_world=None;g.native_callback_mode=255;g.units[0].native_flags64|=32;let old=g.units[0].native_flags9c;assert_eq!(g.native_hardware_common_body(0),Ok(()));assert_eq!(g.units[0].native_flags9c,old);assert_eq!(g.units[0].native_initiative_scan.a4,0);}

#[test]fn ordinary_main_ai_startflag_acquires_and_releases_against_a_live_enemy(){let mut g=field();g.spawn("medium",0,640.,640.,1,None);g.spawn("medium",1,760.,640.,2,None);g.maintain_native_group_rosters();for u in &mut g.units{u.native_phase35=9;u.native_initiative_scan.flags71|=16;u.native_reload7b=0;}let mut released=false;let mut broadcast=false;for tick in 0..120{g.winner=None;g.step(0.059);assert_eq!(g.native_route_boundary,None,"normalAIcallback{tick}");broadcast|=g.native_common_legacy.iter().any(|(_,r)|*r==crate::original_hardware_common::LegacyCall::Broadcast15fb0);released|=g.projectiles.iter().any(|p|p.team==0)||g.events.iter().any(|e|e["kind"]=="shot"&&e["team"]==0);if released{break;}}assert!(released,"normal automatic primary release stays reachable");assert!(broadcast,"existing15fb0backendisexecutedandexplicitlymarked");}

#[test]fn hatch_release_uses_the_existing_secondary_backend_once_after_counter_writes(){let mut g=field();g.spawn("medium",0,640.,640.,1,None);g.spawn("grunt",1,736.,636.,2,None);g.maintain_native_group_rosters();g.native_group_rosters.observe_unit_context(g.units[0].native_slot.unwrap());g.prepare_native_ambient_queries();let w=g.units[0].native_hardware_slot.unwrap();let b=&mut g.native_hardware_pool[w].attributes.bytes;b[25]=3;b[26]=0;b[27]=0;b[5]=60;b[21]=2;g.units[0].native_range4=Some(100);g.units[0].native_phase35=9;g.native_callback_mode=0;g.native_hardware_common_body(0).unwrap();assert_eq!(g.native_route_boundary,None);assert_eq!(g.bullets.len(),1);assert_eq!(g.native_common_legacy.iter().filter(|(_,r)|*r==crate::original_hardware_common::LegacyCall::Secondary5b210).count(),1);assert_eq!(g.native_hardware_pool[w].attributes.bytes[25],4);assert_eq!(g.native_hardware_pool[w].attributes.bytes[34],102);assert_eq!(g.units[0].original_combat.as_ref().unwrap().secondary_state,4);}
#[test]fn apc56_stays_with_its_existing_coupled_passenger_caller(){let mut g=ordinary(56);g.units[0].kind="apc".into();let before=g.native_hardware_common;assert!(!g.dispatch_native_hardware_common(0));assert_eq!(g.units[0].native_counter68,8);assert_eq!(g.native_hardware_common,before);assert_eq!(g.units[0].native_common_callback,None);}

fn fnv(bytes:&[u8])->u32{bytes.iter().fold(2166136261u32,|h,&n|(h^u32::from(n)).wrapping_mul(16777619))}
fn object_field(eligible:bool)->Game{let mut g=field();g.spawn("medium",0,640.,640.,1,None);g.spawn("medium",1,3600.,3600.,2,None);for n in 2..5{g.spawn("grunt",0,2000.+n as f64*64.,2000.,10+n,None);}g.objects.push(serde_json::json!({"type":33,"equipmentId":13,"nativeSlot":0,"x":720,"y":640,"nativeHp":10}));g.import_native_world(&Value::Null);g.maintain_native_group_rosters();g.native_group_rosters.observe_unit_context(g.units[0].native_slot.unwrap());g.prepare_native_ambient_queries();g.units[0].native_phase35=9;g.units[0].native_initiative_scan.flags71=8;g.units[0].native_range4=Some(100);g.native_callback_mode=255;let w=g.units[0].native_hardware_slot.unwrap();g.native_hardware_pool[w].attributes.bytes[21]=2;if eligible{g.units[2].native_phase35=18;}g}
#[test]fn object_hit_checks_the_actual_plus2_plus4_raw_headers_before_any_handoff(){let mut g=object_field(false);assert_eq!(g.native_hardware_common_body(0),Ok(()));assert_eq!(g.units[2].x,2128.);assert_eq!(g.units[4].x,2256.);let mut g=object_field(true);assert_eq!(g.native_hardware_common_body(0),Err(error(Missing::ObjectOrder(0))));assert_eq!((g.units[2].x,g.units[2].y),(640.,640.),"known45ca3awritesprecede578b0boundary");assert_ne!(g.units[2].native_flags64&32,0);}

#[test]fn strategic_direct_caller_replaces_then_prepends_finite_heads_and_starts_real_inline_line(){let mut g=ordinary(9);let slot=g.units[0].native_slot.unwrap();let old=g.native_routes.get_mut().pool.allocate_goal([408,328]).unwrap();g.native_routes.get_mut().pool.links[slot].primary=old;g.native_routes.get_mut().managed[slot]=true;g.replace_original_ai_path(0,[500,400],false);let first=g.native_routes.borrow().pool.links[slot].primary;assert_ne!(first,old);assert_eq!(g.native_routes.borrow().pool.node(first).unwrap(),paths::Node{point:[500,400],next:0});assert!(g.units[0].original_motion.is_some());assert_eq!(g.units[0].native_remaining48,172);assert_eq!((g.units[0].x,g.units[0].y),(640.,640.));g.replace_original_ai_path(0,[500,280],true);let head=g.native_routes.borrow().pool.links[slot].primary;assert_eq!(g.native_routes.borrow().pool.node(head).unwrap(),paths::Node{point:[500,280],next:first});assert_eq!(g.units[0].path.front(),Some(&(984.,544.)));assert!(g.units[0].original_motion.is_some());}
#[test]fn exhausted_direct_allocator_preserves_heads_and_the_caller_still_executes52810(){let mut g=ordinary(9);let slot=g.units[0].native_slot.unwrap();for n in &mut g.native_routes.get_mut().pool.nodes[..240]{n.next=0;}g.native_routes.get_mut().pool.nodes[300]=paths::Node{point:[408,328],next:0};let old=paths::Pool::address(300);g.native_routes.get_mut().pool.links[slot].primary=old;g.native_routes.get_mut().managed[slot]=true;g.replace_original_ai_path(0,[500,400],false);assert_eq!(g.native_routes.borrow().pool.links[slot].primary,old);assert_eq!(g.native_routes.borrow().pool.nodes[300].point,[408,328]);assert!(g.units[0].original_motion.is_some());assert_eq!(g.units[0].native_remaining48,80,"source52810startsretainedoldhead");}

#[test]fn active_bit_query_does_not_invent_a_header_and_constructor_reuse_invalidates_reset_fact(){let mut g=field();g.native_upstream_reactions.clear_for_mission();assert_eq!(g.native_reaction_active(26),Ok(false));assert_eq!(g.native_reaction_source(26),Err(crate::original_upstream_reactions::Boundary::MissingSource(26)));for n in 0..27{g.spawn("grunt",(n&1)as i32,640.+n as f64*40.,1000.,n+1,None);}g.maintain_native_group_rosters();assert_eq!(g.native_reaction_active(26),Ok(true));assert!(g.native_remove_actor(26,false,false));assert_eq!(g.native_reaction_active(26),Ok(false));g.spawn("grunt",0,1800.,900.,90,None);g.maintain_native_group_rosters();let i=g.units.len()-1;assert_eq!(g.units[i].native_slot,Some(26));assert_eq!(g.native_reaction_active(26),Ok(true));g.units[i].native_slot=None;assert_eq!(g.native_reaction_active(26),Err(crate::original_upstream_reactions::Boundary::MissingSource(26)),"constructedbutunprovenmissingheaderdoesnotbecomefalse");}
#[test]fn automatic_aim_calls_existing_resolver_before_scan_without_emitting_an_extra_shot(){let mut g=ordinary(9);let slot=g.units[0].native_slot.unwrap();let target=g.units[1].native_slot.unwrap();g.units[1].x=800.;g.units[1].y=640.;g.initialize_native_walk_fields(1);g.refresh_native_pattern_step(1,0);g.prepare_native_ambient_queries();g.units[0].native_flags64|=8;g.native_group_rosters.members[slot].as_mut().unwrap().flags69&=!128;let w=g.units[0].native_hardware_slot.unwrap();let mut order=g.native_hardware_pool[w].order;order.target=[-4321,target as i16];g.native_hardware_pool[w].set_order(order);g.native_callback_mode=255;g.native_hardware_common_body(0).unwrap();assert_eq!(g.native_hardware_common.gate,0,"449470writerwinsbeforefinal58620gate");assert!(g.projectiles.is_empty());assert!(g.bullets.is_empty());}
#[test]fn actual_mission_reset_prefix_clears_active_flags_in_all240_raw_slots(){let Some(root)=std::env::var_os("NATIVE_COMMON_CALLER_DIRECTORY")else{return;};let rows=std::fs::read_to_string(std::path::Path::new(&root).join("V46-common-unit-reset.jsonl")).unwrap().lines().map(|l|serde_json::from_str::<Value>(l).unwrap()).collect::<Vec<_>>();assert_eq!(rows.len(),16);for row in rows{assert_eq!(row["nonzero"],0);assert_eq!(row["hash"],2066034117u32);assert_eq!(row["edi"],0x5e30c8+240*192);assert_eq!(row["ecx"],0);}}

#[test]fn dummy_order_bytes_have_one_owner_across_common_and_existing_resolver(){let mut g=ordinary(9);g.units[0].native_hardware_slot=None;g.native_hardware_dummy=HardwareOrderRecord{target:[123,456],selected_target12:0xa5,counter13:-7,counter14:12,field17:2};g.native_hardware_dummy_attributes.bytes[5]=99;g.native_hardware_dummy_attributes.bytes[14..24].fill(0xcc);let mut env=Env{game:&mut g,index:0,movement:Hardware::Dummy,probe_crt:false};let mut b=env.bytes(Hardware::Dummy);assert_eq!(HardwareOrderRecord::from_bytes(&b),env.game.native_hardware_dummy);assert_eq!(b[5],99);pw(&mut b,14,-4321);pw(&mut b,16,1);b[18]=3;b[19]=249;b[20]=17;b[23]=0;env.put(Hardware::Dummy,b);assert_eq!(env.game.native_hardware_dummy,HardwareOrderRecord::from_bytes(&b));env.game.native_hardware_dummy.counter14=-23;assert_eq!(env.bytes(Hardware::Dummy)[20],233,"nextreadusesfreshordernotstaleattrs");}

#[test]fn group_suffix_requires_known_main_index_and_preserves_prior_known_writes(){let mut g=ordinary(9);g.units[1].native_trait7a=-37;let a=g.native_group_rosters.members[g.units[0].native_slot.unwrap()].as_ref().unwrap().group as usize;let b=g.native_group_rosters.members[g.units[1].native_slot.unwrap()].as_ref().unwrap().group as usize;g.native_group_rosters.pool[a].roster[61]=1;g.native_group_rosters.pool[b].roster[61]=1;g.native_group_rosters.pool[b].roster[59]=255;let target=g.units[1].native_slot.unwrap()as u8;let mut env=Env{game:&mut g,index:0,movement:Hardware::Pool(0),probe_crt:false};assert_eq!(env.acquire(target),Err(error(Missing::MissingLoopSlot(target))));assert_eq!(env.game.native_group_rosters.pool[b].roster[16],75);assert_eq!(env.game.native_group_rosters.pool[b].roster[62],219);env.game.native_unit_loop_index=0;env.game.native_unit_loop_active=true;assert_eq!(env.acquire(target),Ok(()));assert_eq!(env.game.native_group_rosters.pool[b].roster[59],0);assert_eq!(env.game.native_group_rosters.pool[b].roster[68],0);}
